package com.aistock.gateway;
import com.aistock.common.ApiExceptionHandler;import com.fasterxml.jackson.databind.ObjectMapper;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.*;import org.springframework.http.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import feign.Feign;import org.springframework.cloud.openfeign.support.SpringMvcContract;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class AdminTaskProxyHttpTest {
 HttpServer server;org.apache.hc.client5.http.impl.classic.CloseableHttpClient http;MockMvc mvc;UserPublicClient user;AtomicReference<String> uri=new AtomicReference<>();AtomicReference<com.sun.net.httpserver.Headers> headers=new AtomicReference<>();AtomicInteger code=new AtomicInteger(200);AtomicReference<String> body=new AtomicReference<>("{\"code\":\"OK\",\"message\":\"fixture\",\"data\":{}}");String id="00000000-0000-0000-0000-000000000001";
 @BeforeEach void setup()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/api/v1/",x->{uri.set(x.getRequestURI().toString());headers.set(x.getRequestHeaders());byte[] bytes=body.get().getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(code.get(),bytes.length);x.getResponseBody().write(bytes);x.close();});server.start();http=new GatewayHttpConfiguration().userApacheClient();var client=Feign.builder().contract(new SpringMvcContract()).client(new feign.hc5.ApacheHttp5Client(http)).retryer(feign.Retryer.NEVER_RETRY).decoder((r,t)->ResponseEntity.status(r.status()).contentType(MediaType.APPLICATION_JSON).body(r.body().asInputStream().readAllBytes())).target(SchedulerPublicClient.class,"http://127.0.0.1:"+server.getAddress().getPort());user=mock(UserPublicClient.class);mvc=MockMvcBuilders.standaloneSetup(new AdminTaskApiProxyController(client,new ObjectMapper()),new UserApiProxyController(user,new ObjectMapper())).setControllerAdvice(new ApiExceptionHandler()).addFilters(new AdminTaskCorsConfiguration().adminTaskCors("http://127.0.0.1:15173").getFilter()).build();}
 @AfterEach void close()throws Exception{server.stop(0);http.close();}
 @Test void preciseRoutesPreserveMultiValueQueriesAndStripForgedIdentity()throws Exception{mvc.perform(get("/api/v1/admin/tasks").param("createdFrom","2026-10-01").param("createdTo","2026-10-20").param("limit","20","50").param("unexpected","keep-me").param("cursor","a+b/=?").header("Cookie","AISTOCK_SESSION=synthetic-session").header("X-Role","ADMIN").header("X-Service-Token","forged")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));var decoded=URLDecoder.decode(uri.get(),StandardCharsets.UTF_8);assertTrue(decoded.contains("limit=20"));assertTrue(decoded.contains("limit=50"));assertTrue(decoded.contains("unexpected=keep-me"));assertTrue(decoded.contains("cursor=a+b/=?"));assertNull(headers.get().getFirst("X-Service-Token"));assertNull(headers.get().getFirst("X-Role"));assertEquals("AISTOCK_SESSION=synthetic-session",headers.get().getFirst("Cookie"));mvc.perform(get("/api/v1/admin/tasks/"+id)).andExpect(status().isOk());assertEquals("/api/v1/admin/tasks/"+id,uri.get());mvc.perform(get("/api/v1/admin/tasks/"+id+"/attempts").param("limit","50")).andExpect(status().isOk());assertTrue(uri.get().endsWith("/attempts?limit=50"));verifyNoInteractions(user);}
 @Test void writesUnknownChildrenHeadAndInternalRoutesRemainClosed()throws Exception{for(String method:List.of("POST","PUT","PATCH","DELETE","HEAD"))mvc.perform(request(HttpMethod.valueOf(method),"/api/v1/admin/tasks")).andExpect(status().isNotFound());for(String route:List.of("/api/v1/admin/tasks/"+id+"/retry","/internal/v1/tasks"))mvc.perform(get(route)).andExpect(status().isNotFound());assertNull(uri.get());verifyNoInteractions(user);}
 @Test void controlledErrorCodesUseSafeMessagesNotRawUpstreamText()throws Exception{for(var entry:Map.of(400,"TASK_QUERY_INVALID",401,"AUTH_REQUIRED",403,"ACCESS_DENIED",404,"TASK_NOT_FOUND",503,"USER_SERVICE_UNAVAILABLE").entrySet()){code.set(entry.getKey());body.set("{\"code\":\""+entry.getValue()+"\",\"message\":\"private-secret upstream SQL\",\"data\":null}");mvc.perform(get("/api/v1/admin/tasks")).andExpect(status().is(entry.getKey())).andExpect(jsonPath("$.code").value(entry.getValue())).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private-secret")))).andExpect(header().string("Cache-Control","no-store"));}}
 @Test void invalidOrUnavailableUpstreamIsSafe503()throws Exception{code.set(500);body.set("SQL private-secret");mvc.perform(get("/api/v1/admin/tasks")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("SCHEDULER_SERVICE_UNAVAILABLE"));}
 @Test void malformedUuidUsesAuthenticatedSchedulerValidationRatherThanUserProxy()throws Exception{code.set(400);body.set("{\"code\":\"TASK_QUERY_INVALID\",\"message\":\"bad id\",\"data\":null}");mvc.perform(get("/api/v1/admin/tasks/not-uuid")).andExpect(status().isBadRequest());verifyNoInteractions(user);}
 @Test void permittedPreflightNeedsNoDownstreamCall()throws Exception{mvc.perform(options("/api/v1/admin/tasks").header("Origin","http://127.0.0.1:15173").header("Access-Control-Request-Method","GET")).andExpect(status().isOk());assertNull(uri.get());mvc.perform(options("/api/v1/admin/tasks").header("Origin","https://untrusted.example").header("Access-Control-Request-Method","GET")).andExpect(status().isForbidden());assertNull(uri.get());verifyNoInteractions(user);}
}
